def _iter_run(path: str) -> Iterator[Any]:
    """Yield `(key, ordinal, record)` triples from a spilled run file."""
    with open(path, "r", encoding="utf-8") as fh:
        for line in fh:
            key, ord_value, record = json.loads(line)
            yield (key, ord_value, record)
